using System; using Microsoft.VisualStudio.TestTools.UnitTesting; using TaskTree.Modules.BugReporter;
namespace TaskTree.Modules.BugReporter.Tests{[TestClass]public class BugReportRateLimiterTests{static readonly DateTimeOffset T=new(2026,6,1,12,0,0,TimeSpan.Zero);[TestMethod]public void AllowsFirstSend(){Assert.IsTrue(new BugReportRateLimiter().CanSend(T));}[TestMethod]public void BlocksAfterFiveInMinute(){var r=new BugReportRateLimiter();for(int i=0;i<5;i++)r.RecordSend(T.AddSeconds(i));Assert.IsFalse(r.CanSend(T.AddSeconds(30)));}[TestMethod]public void AllowsAfterMinuteWindow(){var r=new BugReportRateLimiter();for(int i=0;i<5;i++)r.RecordSend(T.AddSeconds(i));Assert.IsTrue(r.CanSend(T.AddMinutes(2)));}[TestMethod]public void BlocksAfterFiftyInDay(){var r=new BugReportRateLimiter();for(int i=0;i<50;i++)r.RecordSend(T.AddMinutes(i+2));Assert.IsFalse(r.CanSend(T.AddHours(23)));}[TestMethod]public void AllowsNextDay(){var r=new BugReportRateLimiter();for(int i=0;i<50;i++)r.RecordSend(T.AddMinutes(i+2));Assert.IsTrue(r.CanSend(T.AddDays(1)));}}}
